import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int MOD = sc.nextInt();

        long[] DP = new long[N];
        long[] Cum = new long[N + 1];

        DP[0] = 1;
        Cum[1] = 1;

        for (int i = 1; i < N; i++) {
            int i2 = N - i;
            long total_value = Cum[i];
            int j = 2;
            while (true) {
                if (i2 * j > N) {
                    break;
                }
                long startIndex = N - i2 * j + 1;
                long endIndex = Math.max(0, N - i2 * j - j + 1);
                total_value += Cum[(int)startIndex] - Cum[(int)endIndex];
                total_value %= MOD;
                j++;
            }
            Cum[i + 1] = (Cum[i] + total_value) % MOD;
            DP[i] = total_value;
        }
        System.out.println(DP[N - 1]);
        sc.close();
    }
}

